INSERT INTO programs (id,name,category,min_age,max_age,description,outcome_label,details) VALUES ('harbor','Harbor Mentors','Mentoring',11,14,'A steady connection with a trusted adult. Students meet with a volunteer mentor to build confidence, set school and personal goals, and strengthen their support network.','Confidence and connection to a trusted adult','{"tagline":"A trusted adult. A stronger start.","audience":"Students ages 11–14 and their guardians.","format":"Weekly small-group mentoring with individual mentor check-ins. Each mentor supports four students.","schedule":"Tuesdays, 3:30–4:30 p.m., during the school term.","locations":["Bayview Middle School · Little Havana (fictional)"],"languages":["English","Spanish","Haitian Creole"],"lead":"Program manager, with an authorized session leader and volunteer coordinator.","staffing":"One session leader and five screened volunteer mentors for the 20-student demo cohort.","activities":["Personal goal check-ins","Listening and communication practice","School transitions and trusted-adult mapping"],"measures":["Unique enrolled students and attended sessions","Active mentor assignments and approved volunteer hours","Paired confidence/connection self-assessments, with missing responses disclosed"],"access":"Guardian registration and staff-confirmed mentor assignment.","followup":"Two consecutive unexplained absences create an assigned family check-in.","capacity":"20 students in the demonstration cohort.","record_scope":"Program coordination, attendance and non-clinical feedback.","attendance_rule":"consecutive_absences","enrollment_mode":"app"}');
INSERT INTO programs (id,name,category,min_age,max_age,description,outcome_label,details) VALUES ('compass','Family Compass','Family counseling',0,18,'Confidential family counseling for children and their caregivers, coordinated by TidePath’s lead counselor. Families can request support with communication, stressful changes, and staying connected to appropriate help.','Service access and continuity, defined within the secure counseling system','{"tagline":"Support for the whole family.","audience":"Children up to age 18 and their caregivers. Eligibility and service planning are assessed by counseling staff.","format":"Private family appointments, with the service plan and frequency determined by counseling staff.","schedule":"By appointment; availability confirmed privately by the counseling team.","locations":["Little Havana Family Center (fictional)","West Little River Community Center (fictional)"],"languages":["English","Spanish","Haitian Creole"],"lead":"Lead counselor, supervising two counselors.","staffing":"The existing three-person counseling team; interpreter arrangements confirmed by staff when needed.","activities":["Private intake and service planning","Family counseling appointments","Coordination of appropriate referrals"],"measures":["Only authorized aggregate service-access measures from the secure system","Any clinical measures are defined and retained by counseling staff"],"access":"Families request a private conversation with the front-desk coordinator or counseling team. No clinical intake through this demo.","followup":"Appointments and missed-appointment follow-up are handled privately in the secure counseling system.","capacity":"Appointment availability is managed by the counseling team; no invented client-capacity figure.","record_scope":"Catalog information only here. No client identities, enrollment, appointment attendance, diagnoses, treatment plans or counseling notes.","attendance_rule":"external","enrollment_mode":"secure_system"}');
INSERT INTO programs (id,name,category,min_age,max_age,description,outcome_label,details) VALUES ('nextwave','Next Wave Safety Labs','Safety workshops',11,14,'Practical school-based workshops where students identify trusted adults, practice asking for help, explore safe choices online and in their neighborhood, and learn respectful ways to handle conflict.','Confidence identifying trusted adults and asking for help','{"tagline":"Practice safety. Build confidence.","audience":"Middle-school students ages 11–14.","format":"Interactive classroom workshops with scenarios, discussions and short group activities.","schedule":"Bayview: Wednesdays; Riverside: Thursdays, 3:30–5:00 p.m.","locations":["Bayview Middle School · Little Havana (fictional)","Riverside Middle School · West Little River (fictional)"],"languages":["English","Spanish","Haitian Creole"],"lead":"Program manager with school session leaders.","staffing":"One authorized session leader and two volunteer facilitators per school.","activities":["Trusted-adult and safe-place mapping","Respectful conflict scenarios","Digital and neighborhood safety practice"],"measures":["Unique students, enrollment and completed workshop attendance","Non-clinical help-seeking confidence self-assessments","Owned follow-ups and unresolved attendance issues"],"access":"Guardian registration into one school group; school transfers preserve earlier records.","followup":"Two consecutive unexplained absences trigger an owned family check-in.","capacity":"30 demo students; Bayview capacity 15, Riverside capacity 16 including an approved transfer seat.","record_scope":"Educational participation and non-clinical feedback.","attendance_rule":"consecutive_absences","enrollment_mode":"app"}');
INSERT INTO programs (id,name,category,min_age,max_age,description,outcome_label,details) VALUES ('brightminds','Bright Minds, Strong Connections','Mental health workshops',11,18,'Community-center education that helps young people recognize emotions, build everyday coping and communication skills, reduce stigma around seeking support, and identify trusted adults and services. Workshops are education, not individual counseling.','Confidence identifying support and asking for help','{"tagline":"Understand feelings. Find support.","audience":"Young people ages 11–18, with activities adapted for the group’s age range.","format":"Facilitated group education using age-appropriate discussion, reflection and skills practice. No clinical screening is stored here.","schedule":"Little Havana: Mondays; West Little River: Fridays, 4:00–5:30 p.m.","locations":["Little Havana Family Center (fictional)","West Little River Community Center (fictional)"],"languages":["English","Spanish","Haitian Creole"],"lead":"Lead counselor oversees workshop content; authorized facilitators deliver the educational sessions.","staffing":"One session leader and two volunteer facilitators per 15-person group.","activities":["Naming emotions and recognizing support networks","Everyday communication and help-seeking practice","Learning when and how to approach a trusted adult"],"measures":["Completed educational sessions and unique participants","Voluntary non-clinical support-confidence self-assessments","Participation follow-ups without clinical details"],"access":"Guardian registration for one community-center group. Private support requests go to the counseling team.","followup":"Two consecutive unexplained absences trigger a supportive program check-in, never an inferred diagnosis.","capacity":"30 demo students across two 15-person groups; each group has capacity for 20.","record_scope":"Workshop participation only; no diagnoses, symptoms, therapy notes or treatment outcomes.","attendance_rule":"consecutive_absences","enrollment_mode":"app"}');
INSERT INTO programs (id,name,category,min_age,max_age,description,outcome_label,details) VALUES ('together','Neighborhood Together','Community events',0,18,'Welcoming neighborhood gatherings that connect children and caregivers with TidePath staff, volunteers, school resources and practical family support. Activities include back-to-school preparation, family games, resource tables and supply distribution.','Family participation and connections to community resources','{"tagline":"Meet your neighbors. Find your people.","audience":"Children up to age 18 and their caregivers in Little Havana and West Little River.","format":"Optional family events with supervised activities and resource tables. Child check-in is recorded separately from any adult attendance.","schedule":"Three demo Saturdays: July 25, August 22 and September 19, 10:00 a.m.–noon.","locations":["Little Havana Family Center (fictional)","West Little River Community Center (fictional)"],"languages":["English","Spanish","Haitian Creole"],"lead":"Volunteer coordinator, with Marisol coordinating program resources.","staffing":"A staff event lead, volunteer event helpers and supply drivers. Drivers support supplies; child transportation is not implied.","activities":["Back-to-school resource fair","Family activity morning","Neighborhood resource and supply day"],"measures":["Unique registered children and child check-ins","Distinct participating households, when recorded","Approved event-helper and supply-driver hours; adult walk-ins are not inferred"],"access":"Guardian registration or staff-assisted registration, with caregivers attending alongside children.","followup":"Optional event nonattendance does not trigger a missed-session concern.","capacity":"50 registered demo children; registration capacity 60. This is not a building occupancy figure or an adult headcount.","record_scope":"Event registration, child check-ins and volunteer contributions.","attendance_rule":"optional","enrollment_mode":"app"}');
